<?php
namespace Semizzy\Addons\BulkSms\Http\Controllers;
use App\Http\Controllers\Controller; use Illuminate\Http\Request; use Inertia\Inertia; use Semizzy\Addons\BulkSms\Models\BulkSmsCampaign; use Semizzy\Addons\BulkSms\Models\BulkSmsContact; use Semizzy\Addons\BulkSms\Models\BulkSmsProduct; use Semizzy\Addons\BulkSms\Models\BulkSmsSenderId; use Semizzy\Addons\BulkSms\Services\BulkSmsService;
final class BulkSmsController extends Controller {
 public function index(Request $r){return Inertia::render('BulkSms',['products'=>BulkSmsProduct::where('active',true)->get(['id','key','name','currency','price_per_sms_minor','max_recipients']),'campaigns'=>BulkSmsCampaign::where('user_id',$r->user()->id)->latest()->paginate(20),'contacts'=>BulkSmsContact::where('user_id',$r->user()->id)->where('subscribed',true)->latest()->limit(500)->get(),'sender_ids'=>BulkSmsSenderId::where('user_id',$r->user()->id)->latest()->get()]);}
 public function send(Request $r,BulkSmsService $s){$d=$r->validate(['product_key'=>'required|string|max:80','sender'=>'required|string|max:40','message'=>'required|string|max:1000','phones'=>'required|array|min:1','phones.*'=>'required|string|max:32','scheduled_at'=>'nullable|date','idempotency_key'=>'required|string|max:128']);return response()->json($s->createCampaign($r->user()->id,$d,$d['phones']),201);}
 public function contact(Request $r){$d=$r->validate(['name'=>'nullable|string|max:120','phone'=>'required|string|max:32','group_name'=>'nullable|string|max:100']);$d['user_id']=$r->user()->id;return response()->json(BulkSmsContact::updateOrCreate(['user_id'=>$d['user_id'],'phone'=>$d['phone']],$d),201);}
}
